<?php
declare(strict_types=1);
/**
 * install_admin_db_backup_manager_v1_6_v001.php
 * VERSION: v001
 * LAST MODIFIED: 8/29/2026 6:20:08 am
 * LOCATION: public_html/
 */
date_default_timezone_set('America/New_York');
const BASE_SHA256 = '0172fb4b0f390bfcd1e9cfbdbeaf82b1c20f34b00db12c6acd3def3f136661cc';
const NEW_SHA256 = '527bf157504e2048439e421fc63147fa4a383fc6eaf3f3df0bf858a5b6c4ea95';
$target = __DIR__ . '/admin_db_backup.php';
$replacement = base64_decode('', true);

function ih(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function row(string $label, bool $ok, string $detail=''): void {
    echo '<tr><td>'.ih($label).'</td><td class="'.($ok?'ok':'bad').'">'.($ok?'PASS':'FAIL').'</td><td>'.ih($detail).'</td></tr>';
}
function atomic_write(string $path, string $data): bool {
    $tmp=$path.'.tmp_'.bin2hex(random_bytes(4));
    if(file_put_contents($tmp,$data,LOCK_EX)===false)return false;
    if(!@rename($tmp,$path)){@unlink($tmp);return false;}
    return true;
}

$exists=is_file($target);
$currentHash=$exists?(string)hash_file('sha256',$target):'';
$baselineOk=$exists && $currentHash===BASE_SHA256
    && strpos((string)file_get_contents($target),'Archive Checked')!==false
    && strpos((string)file_get_contents($target),'Permanently Delete Checked Eligible Files')!==false;
$replacementOk=is_string($replacement)
    && hash('sha256',$replacement)===NEW_SHA256
    && strpos($replacement,'v1.6  (8/29/2026 6:20:08 am)')!==false
    && strpos($replacement,"\$oldName = trim((string)(\$_POST['restore_file'] ?? ''));")!==false
    && strpos($replacement,'setBackupChecks')!==false
    && strpos($replacement,'wireRenameAutoFill')!==false;
$preflightOk=$baselineOk&&$replacementOk;
$apply=isset($_POST['apply'])&&$_POST['apply']==='1';
$messages=[];$success=false;

if($apply&&$preflightOk){
    $backupDir=__DIR__.'/_migration_backups/admin_db_backup_v16_'.date('Ymd_His');
    $ok=is_dir($backupDir)||mkdir($backupDir,0755,true);
    if(!$ok)$messages[]='FAIL: Could not create installer backup directory.';
    if($ok&&!copy($target,$backupDir.'/admin_db_backup.php')){ $ok=false;$messages[]='FAIL: Could not back up admin_db_backup.php v1.5.'; }
    elseif($ok)$messages[]='PASS: Backed up admin_db_backup.php v1.5.';
    if($ok&&!atomic_write($target,$replacement)){ $ok=false;$messages[]='FAIL: Could not install admin_db_backup.php v1.6.'; }
    elseif($ok)$messages[]='PASS: Installed admin_db_backup.php v1.6.';

    if($ok){
        $installed=(string)file_get_contents($target);
        $checks=[
            'v1.6 version history'=>strpos($installed,'v1.6  (8/29/2026 6:20:08 am)')!==false,
            'Rename uses selected radio'=>strpos($installed,"\$oldName = trim((string)(\$_POST['restore_file'] ?? ''));")!==false,
            'Active rename auto-fill'=>strpos($installed,"wireRenameAutoFill('active-backup-form'")!==false,
            'Archive rename auto-fill'=>strpos($installed,"wireRenameAutoFill('archive-backup-form'")!==false,
            'Active Select All / Clear'=>strpos($installed,"setBackupChecks('active', true)")!==false,
            'Archive Select All / Clear'=>strpos($installed,"setBackupChecks('archive', true)")!==false,
            'Delete Select All / Clear'=>strpos($installed,"setBackupChecks('delete', true)")!==false,
            'v1.5 quarantine retained'=>strpos($installed,'Move Checked to To Be Deleted')!==false,
            'v1.5 age gate retained'=>strpos($installed,"if (!\$info['eligible'])")!==false,
            'replacement hash exact'=>hash_file('sha256',$target)===NEW_SHA256,
        ];
        foreach($checks as $label=>$pass){ $messages[]=($pass?'PASS: ':'FAIL: ').$label;if(!$pass)$ok=false; }
    }
    if(!$ok&&is_file($backupDir.'/admin_db_backup.php')){
        if(copy($backupDir.'/admin_db_backup.php',$target))$messages[]='ROLLBACK: Restored admin_db_backup.php v1.5.';
        else $messages[]='ROLLBACK ERROR: Could not restore admin_db_backup.php v1.5.';
    } else $success=true;
}
?><!doctype html>
<html><head><meta charset="utf-8"><title>Install DB Backup Manager v1.6</title>
