<li>Radio buttons are never changed by Select All / Clear.</li>
<li>All v1.5 archive, quarantine, 30-day delete gate, restore and backup behavior is preserved.</li>
</ul><?php if(!$apply): ?><form method="post"><input type="hidden" name="apply" value="1"><button>Install DB Backup Manager v1.6</button></form><?php endif; ?></div><?php endif; ?>
<?php if($apply): ?><div class="card"><h2>Apply Result</h2><p class="<?php echo $success?'ok':'bad'; ?>"><strong><?php echo $success?'SUCCESS':'FAILED / ROLLED BACK'; ?></strong></p><ul><?php foreach($messages as $m): ?><li><?php echo ih($m); ?></li><?php endforeach; ?></ul><?php if($success): ?><p><a href="/admin_db_backup.php" target="_blank">Open Admin DB Backup Manager v1.6</a></p><?php endif; ?></div><?php endif; ?>
</div></body></html>